tool_args.command:
pip install texcount 2>/dev/null; perl -e '
# Simple word count: treat each $...$ as 1 word, strip LaTeX commands
my $text = do { local $/; <STDIN> };
$text =~ s/\$[^$]+\$/MATHEXPR/g;  # each math block = 1 word
$text =~ s/\\[a-zA-Z]+//g;         # strip commands
$text =~ s/[{}~]/ /g;              # strip braces
$text =~ s/---/ /g;
$text =~ s/--/-/g;
$text =~ s/\s+/ /g;
my @words = grep { /\S/ } split /\s+/, $text;
print scalar(@words), " words (math-as-one-word count)\n";
' < /home/ubuntu/.agent-ml-research-idea_gen_0509_10/projects/provenance_weight_training/docs/paper/sections/abstract.tex
